mapper.select:
select *
  from rule_version
 where rule_id = #{ruleId}
   and version = #{version}

mapper.update:
update operation_plan
   set status = 'FAILED',
       version = version + 1,
       updated_by = #{updatedBy},
       updated_at = #{updatedAt}
 where id = #{id}
   and status = 'RUNNING'
   and version = #{version}
